import{_ as e,o,c as a,ag as r}from"./chunks/framework.BKVF-9lJ.js";const u=JSON.parse('{"title":"Comparison","description":"","frontmatter":{},"headers":[],"relativePath":"comparison.md","filePath":"comparison.md","lastUpdated":1791840224000}'),d={name:"comparison.md"};function n(i,t,s,c,l,p){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;">​</a></h1><p>MFE Forge sits in a crowded space. This page explains what it does and does not do relative to common alternatives, so you can decide whether it fits. Descriptions of other tools are kept general; check their own documentation for current details.</p><h2 id="what-mfe-forge-is" tabindex="-1">What MFE Forge is <a class="header-anchor" href="#what-mfe-forge-is" aria-label="Permalink to &quot;What MFE Forge is&quot;">​</a></h2><ul><li>A <strong>convention-based scaffolder and synchroniser</strong> for Vite + React 19 micro frontends that use Module Federation through <code>@originjs/vite-plugin-federation</code>.</li><li>A set of <strong>small runtime helpers</strong> (error boundary, lazy remote loading, event bus, Zustand stores, router helpers, tokens, test utilities).</li><li><strong>Pre-1.0.</strong> APIs and templates may change between minor versions.</li></ul><h2 id="what-it-is-not" tabindex="-1">What it is not <a class="header-anchor" href="#what-it-is-not" aria-label="Permalink to &quot;What it is not&quot;">​</a></h2><ul><li>Not a build system or task runner with caching. <code>build</code> runs each app&#39;s <code>build</code> script sequentially.</li><li>Not a federation runtime. Loading is done by the federation plugin; MFE Forge generates its configuration.</li><li>Not framework-agnostic. Templates are React-only. The config schema accepts <code>vue</code> and <code>svelte</code> as <code>defaults.framework</code> values, but no templates exist for them.</li><li>Not a deployment platform. Production remote URLs are not managed yet; see <a href="./publishing">Publishing</a>.</li></ul><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>MFE Forge (0.x)</th><th>Nx</th><th>Turborepo</th><th>single-spa</th><th>Module Federation tooling (<code>@module-federation/*</code>)</th></tr></thead><tbody><tr><td>Primary purpose</td><td>MFE scaffolding and host/remote sync for Vite + React</td><td>Monorepo build system with generators and plugins</td><td>Monorepo task runner with caching</td><td>Framework-agnostic MFE router and lifecycle</td><td>Federation runtime and bundler plugins</td></tr><tr><td>Generates hosts and remotes</td><td>Yes (<code>generate host</code>, <code>generate app</code>)</td><td>Yes, through its Module Federation generators</td><td>No</td><td>Through its own CLI</td><td>Not the focus</td></tr><tr><td>Keeps host <code>remotes</code> in sync with the filesystem</td><td>Yes, regex-based (<code>sync</code>)</td><td>Through its own conventions</td><td>No</td><td>Not applicable (import maps)</td><td>No</td></tr><tr><td>Remote type declarations</td><td>Generic <code>ComponentType</code> declarations written by <code>sync</code></td><td>Depends on setup</td><td>No</td><td>No</td><td>MF 2.0 can generate types from remotes</td></tr><tr><td>Task caching</td><td>No</td><td>Yes</td><td>Yes</td><td>No</td><td>No</td></tr><tr><td>Bundlers</td><td>Vite 5.4 only</td><td>Several</td><td>Any</td><td>Any</td><td>Webpack, Rspack, Vite and others</td></tr><tr><td>Frameworks</td><td>React 19</td><td>Many</td><td>Any</td><td>Many</td><td>Any</td></tr><tr><td>Runtime helpers</td><td>Error boundary, loader, event bus, stores, router, tokens, testing</td><td>Not in scope</td><td>Not in scope</td><td>Lifecycles, parcels</td><td>Runtime API and plugins</td></tr><tr><td>Maturity</td><td>Pre-1.0, single maintainer</td><td>Mature</td><td>Mature</td><td>Mature</td><td>Mature</td></tr></tbody></table><h2 id="choosing" tabindex="-1">Choosing <a class="header-anchor" href="#choosing" aria-label="Permalink to &quot;Choosing&quot;">​</a></h2><p><strong>Consider MFE Forge if</strong> you are starting a new React + Vite micro frontend setup, want scope-based structure (<code>apps/&lt;scope&gt;/&lt;name&gt;</code>) with derived names and ports, and are comfortable with a young tool whose templates you may edit by hand.</p><p><strong>Consider Nx</strong> if you need a full monorepo build system with caching, affected-based CI, many frameworks and an established plugin ecosystem.</p><p><strong>Consider Turborepo</strong> if you already have working MFEs and mainly need fast, cached task orchestration. MFE Forge and Turborepo do different jobs; the MFE Forge repository itself uses Turborepo for its own tasks.</p><p><strong>Consider single-spa</strong> if you need to mix frameworks (React, Vue, Angular) in one page or migrate a legacy app gradually through import maps.</p><p><strong>Consider using <code>@module-federation/vite</code> or the Module Federation 2.0 runtime directly</strong> if you need its manifest, runtime plugins, type generation or Rspack interoperability today. MFE Forge plans to adopt it (roadmap phase B, <code>0.2.0</code>), but the current templates use <code>@originjs/vite-plugin-federation</code>.</p><h2 id="combining-tools" tabindex="-1">Combining tools <a class="header-anchor" href="#combining-tools" aria-label="Permalink to &quot;Combining tools&quot;">​</a></h2><p>MFE Forge projects are ordinary npm/Bun/pnpm workspaces. You can add Turborepo or Nx on top for caching, replace the federation plugin in a single app&#39;s <code>vite.config.ts</code>, or use only the runtime packages (<code>@mfe-forge/core</code>, <code>store</code>, <code>router</code>) in an existing federation setup without the CLI.</p>',16)])])}const g=e(d,[["render",n]]);export{u as __pageData,g as default};
